+	putFile(t, kp+nextSuffix, staged)
+	if _, err := OpenSealed(vp, kp, alpha); !errors.Is(err, ErrNoSlotOpens) {
+		t.Fatalf("dropped host with the staged file: %v", err)
+	}
+	w, err := OpenSealed(vp, kp, Passphrase(testPass))
